CREATE OR REPLACE FUNCTION public.advance_match_round(p_match_id uuid, p_expected_round integer, p_ai_score_delta integer DEFAULT 0) RETURNS TABLE(ok boolean, code text, round_id uuid, current_round integer, status public.match_status, sequence integer, advanced boolean) LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'pg_catalog, public, pg_temp' AS $$ DECLARE v_match public.matches%ROWTYPE; v_round public.rounds%ROWTYPE; v_human_count integer; v_submission_count integer; v_next_round integer; v_now timestamptz := clock_timestamp(); v_ai_delta integer := LEAST(GREATEST(COALESCE(p_ai_score_delta,0),0),1000); BEGIN IF p_match_id IS NULL OR p_expected_round IS NULL THEN RETURN QUERY SELECT false,'INVALID_ARGUMENT',NULL::uuid,NULL::integer,NULL::public.match_status,NULL::integer,false; RETURN; END IF; SELECT m.* INTO v_match FROM public.matches AS m WHERE m.id=p_match_id FOR UPDATE; IF NOT FOUND THEN RETURN QUERY SELECT false,'MATCH_NOT_FOUND',NULL::uuid,NULL::integer,NULL::public.match_status,NULL::integer,false; RETURN; END IF; IF v_match.status IN ('MATCH_FINISHED','FINAL_RESULT','MATCH_TERMINATED') THEN RETURN QUERY SELECT false,'MATCH_FINISHED',NULL::uuid,v_match.current_round,v_match.status,v_match.sequence,false; RETURN; END IF; IF v_match.current_round<>p_expected_round THEN RETURN QUERY SELECT false,'STALE_ROUND',NULL::uuid,v_match.current_round,v_match.status,v_match.sequence,false; RETURN; END IF; SELECT r.* INTO v_round FROM public.rounds AS r WHERE r.match_id=p_match_id AND r.round_number=p_expected_round FOR UPDATE; IF NOT FOUND THEN RETURN QUERY SELECT false,'ROUND_NOT_FOUND',NULL::uuid,v_match.current_round,v_match.status,v_match.sequence,false; RETURN; END IF; IF v_round.status='finished' THEN RETURN QUERY SELECT false,'ROUND_ALREADY_FINISHED',v_round.id,v_match.current_round,v_match.status,v_match.sequence,false; RETURN; END IF; SELECT COUNT(*)::integer INTO v_human_count FROM public.match_participants AS mp WHERE mp.match_id=p_match_id AND COALESCE(mp.is_ai,false)=false AND mp.user_id IS NOT NULL; SELECT COUNT(DISTINCT s.user_id)::integer INTO v_submission_count FROM public.answer_submissions AS s WHERE s.round_id=v_round.id AND s.user_id IS NOT NULL; IF (v_round.server_end_at IS NULL OR v_round.server_end_at>v_now) AND v_submission_count<v_human_count THEN RETURN QUERY SELECT false,'ROUND_NOT_READY',v_round.id,v_match.current_round,v_match.status,v_match.sequence,false; RETURN; END IF; IF NOT COALESCE(v_round.ai_score_applied,false) AND EXISTS (SELECT 1 FROM public.match_participants AS ai_mp WHERE ai_mp.match_id=p_match_id AND COALESCE(ai_mp.is_ai,false)=true) THEN UPDATE public.match_participants AS mp SET score=COALESCE(mp.score,0)+v_ai_delta WHERE mp.match_id=p_match_id AND COALESCE(mp.is_ai,false)=true; UPDATE public.rounds AS r SET ai_score_applied=true WHERE r.id=v_round.id; END IF; UPDATE public.rounds AS r SET status='finished',sequence=COALESCE(r.sequence,0)+1 WHERE r.id=v_round.id; v_next_round:=v_match.current_round+1; IF v_next_round>v_match.total_rounds THEN UPDATE public.matches AS m SET status='MATCH_FINISHED',sequence=COALESCE(m.sequence,0)+1,server_now=v_now,ended_at=COALESCE(m.ended_at,v_now) WHERE m.id=p_match_id; RETURN QUERY SELECT true,'MATCH_FINISHED',v_round.id,v_match.current_round+1,'MATCH_FINISHED'::public.match_status,v_match.sequence+1,true; RETURN; END IF; UPDATE public.matches AS m SET current_round=v_next_round,status='ROUND_STARTING',sequence=COALESCE(m.sequence,0)+1,server_now=v_now WHERE m.id=p_match_id; RETURN QUERY SELECT true,'ADVANCED',v_round.id,v_next_round,'ROUND_STARTING'::public.match_status,v_match.sequence+1,true; END; $$; REVOKE ALL ON FUNCTION public.advance_match_round(uuid, integer, integer) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.advance_match_round(uuid, integer, integer) TO service_role;
